import React from "react";

export default function EventCard({ event, onClick }) {
  return (
    <div
      onClick={onClick}
      style={{
        border: "1px solid #ccc",
        width: 300,
        borderRadius: 10,
        padding: 10,
        cursor: "pointer"
      }}
    >
      <img
        src={event.image}
        alt={event.title}
        style={{
          width: "100%",
          height: 150,
          objectFit: "cover",
          borderRadius: 10
        }}
      />
      <h3>{event.title}</h3>
      <p>{event.date}</p>
    </div>
  );
}
